        uint256 totalRaised;
        /// @dev Price in quote per 1 token (scaled 1e18), if applicable.
        uint256 lastPrice;
    }

    struct FeeTier {
        address recipient;
        uint16 bps;
    }

    /// @dev Settlement passed from OpenFourCore to vault after FeeRouter payment (`TradePaymentResult`).
    struct VaultTradeParams {
        address trader;
        uint256 tokenAmount;
        uint256 curveQuote;
        uint256 protocolFee;
        uint256 taxFee;
        uint256 devFee;
        uint256 antiSniperQuote;
    }

    struct TradeContext {
        address token;
        address trader;
        uint256 amount;
        bool isBuy;
        uint256 timestamp;
        uint256 blockNumber;
        uint256 remainingForSale;
        uint256 totalRaised;
        uint256 curveQuote;
        bytes proof;
    }

    struct TradeResult {
        bool allowed;
        uint256 minAmount;
        uint256 maxAmount;
        FeeTier[] fees;
        /// @dev ABI-encoded revert payload used when `allowed` is false.
        bytes revertData;
    }

    /// @dev Bubbles a trade module's rejection payload unchanged.
    function revertIfDisallowed(TradeResult memory result) internal pure {
        if (result.allowed) return;
        bytes memory data = result.revertData;
        if (data.length == 0) revert TradeNotAllowed();
        assembly ("memory-safe") {
            revert(add(data, 0x20), mload(data))
        }
    }

    struct TradeHookContext {
        address token;
        address trader;
        uint256 requestedAmount;
        uint256 executedAmount;
        bool isBuy;
        uint256 timestamp;
        uint256 blockNumber;
        uint256 curveQuote;
        /// @dev Trader's actual quote flow: grossQuote + totalFee on buy, grossQuote - totalFee on sell.
        uint256 traderQuote;
        bytes proof;
    }

    struct MigrateContext {
        address token;
        uint256 totalRaised;
        uint256 remainingForSale;
        bool soldOut;
        uint256 timestamp;
    }

    struct MigrateResult {
        bool canMigrate;
        bytes data;
        string reason;
    }

    struct MigrateHookContext {
        address vault;
        address token;
        address quoteAsset;
        address creator;
        uint256 totalRaised;
        uint256 remainingForSale;
        uint256 timestamp;
    }
}

